const canonicalSong=(title,artist)=>[title,artist].map(value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')).join('-');
function queueSharedPractice(state,active,part){if(!state.sharingAccount||!part.seconds)return;if(active.socialAccount!==state.sharingAccount){active.socialAccount=state.sharingAccount;active.socialDates={};}active.socialDates??={};state.socialQueue??=[];let slot=active.socialDates[part.date];if(!slot||typeof slot==='string')slot=active.socialDates[part.date]={id:globalThis.crypto.randomUUID(),seconds:0};slot.seconds=Math.min(86400,slot.seconds+part.seconds);let record=state.socialQueue.find(r=>r.id===slot.id);if(!record){const song=state.songs.find(s=>s.id===active.songId);if(!song)return;record={id:slot.id,accountId:state.sharingAccount,date:part.date,songKey:canonicalSong(song.title,song.artist),title:song.title,artist:song.artist,seconds:slot.seconds};state.socialQueue.push(record);}else record.seconds=slot.seconds;}
