 openPanel(title,content){this.history?.reset();this.openSetId=null;this.dialog.innerHTML='<button class="close" data-close="socialDialog" aria-label="Close">×</button><h2>'+title+'</h2>'+content;if(!this.dialog.open)this.dialog.showModal();}
 renderAccount(){const e=socialEscape;this.openPanel('Account','<div class="jam-account-name">'+e(this.profile.display_name)+'</div><label class="jam-share-control"><span><strong>Share practice</strong><small>Share online status, the song you’re practicing, and new practice time with friends and shared-set members.</small></span><input type="checkbox" data-social="sharing" '+(this.profile.share_practice?'checked':'')+'></label><p class="section-note">Notes and lesson links stay private. Best attempts have separate sharing controls.</p><label class="jam-share-control"><span><strong>Share repertoire & history</strong><small>Let accepted friends see your songs and daily practice totals, including past sessions.</small></span><input type="checkbox" data-social="repertoire-sharing" '+(this.profile.share_repertoire?'checked':'')+' '+(!this.profile.share_practice?'disabled':'')+'></label><div class="jam-code"><span>Your friend code</span><code>'+e(this.profile.friend_code)+'</code><button class="secondary" data-social="copy-code">Copy</button></div><button class="text-button jam-signout" data-social="signout">Sign out</button>');}
 renderAddFriend(){this.openPanel('Add friend','<form id="socialFormFriend"><label class="field">Friend code<input name="code" placeholder="Enter a friend code" required maxlength="64" autocomplete="off"></label><div class="form-actions"><button class="primary">Send request</button></div></form><div class="jam-code"><span>Your friend code</span><code>'+socialEscape(this.profile.friend_code)+'</code><button class="secondary" data-social="copy-code">Copy</button></div>');}
