 editSet(id=null){const group=id?this.set(id):null;this.openSetId=null;const e=socialEscape,songs=this.hooks.state().songs,byKey=new Map();for(const song of songs)byKey.set(canonicalSong(song.title,song.artist),song);if(group)for(const song of group.songs)if(!byKey.has(song.song_key))byKey.set(song.song_key,{id:song.song_key,title:song.title,artist:song.artist,bpm:song.bpm,minutes:song.minutes});this.editSongs=[...byKey.values()];this.dialog.innerHTML='<button class="close" data-close="socialDialog" aria-label="Close set editor">×</button><h2>'+(group?'Edit shared set':'Create shared set')+'</h2><form id="socialFormSet" data-set-id="'+e(id||'')+'"><label class="field">Set name<input name="name" maxlength="100" value="'+e(group?.name||'')+'" required></label><div class="set-song-picker">'+this.editSongs.map((s,i)=>{const current=group?.songs.find(item=>item.song_key===canonicalSong(s.title,s.artist));return '<label class="set-pick-row"><input type="checkbox" name="song" value="'+i+'" '+(current?'checked':'')+'><span>'+e(s.title)+'<small>'+e(s.artist)+'</small></span><input type="number" min="1" max="180" value="'+(current?.minutes||s.minutes||10)+'" data-song-minutes="'+i+'" aria-label="Target minutes for '+e(s.title)+'"><small>min</small></label>';}).join('')+'</div><div class="form-actions"><button type="button" class="secondary" data-close="socialDialog">Cancel</button><button class="primary">Save set</button></div></form>';if(!this.dialog.open)this.dialog.showModal();}
